#!/usr/bin/env bash
#
# prepare-commit-msg hook: puts a commit message generated by cmai at the top
# of the message that git opens in the editor.
# Installed by install-git-commit-ai.sh (https://github.com/mittwald/ai-developer-tools).
#
# The hook never blocks a commit. If the generation fails, the hook reports the
# reason and git opens the editor without a generated message.
#
# Runs with bash 3.2 or later on Linux, macOS and Windows (Git for Windows).

MSG_FILE="${1:-}"
SOURCE="${2:-}"   # empty for a plain `git commit`; else message, template, merge, squash or commit

MAX_ATTEMPTS=3
TIMEOUT_SECONDS=30            # limit of the first attempt
TIMEOUT_INCREASE_PERCENT=50   # growth of the limit after each timeout: 30s, 45s, 68s
KILL_AFTER_SECONDS=2          # time for cmai to stop before the hook kills it
KEYCHAIN_SECONDS=10           # limit for reading the API key from the system keychain

# The installer writes the name of the keychain entry to this file when it
# stores the API key in the system keychain.
KEYCHAIN_FILE="${HOME}/.config/git-commit-ai/keychain"
KEYCHAIN_ACCOUNT='api-key'

case "${SOURCE}" in
  message|merge|squash|template|commit) exit 0 ;;
esac
[ -n "${MSG_FILE}" ] || exit 0

# Status texts with a remark, as "text|remark". While cmai runs, the line
# shows "<text>...". When cmai is done, it becomes "<text>... <remark>".
# ASCII only, no line longer than 72 (text and remark together).
MESSAGES=(
  'Asking the diff what it did this time|It confessed.'
  'Translating your changes into human|Fluent now.'
  'Teaching the model to say "fix" politely|Manners acquired.'
  'Squinting at your staged changes|Eyes adjusted.'
  'Pretending this was the plan all along|Nobody suspects a thing.'
  'Turning chaos into Conventional Commits|Order restored!'
  'Finding a nicer word for "oops"|Found one.'
  'Counting the files you swear you never touched|Your secret is safe.'
  'Blaming the previous commit|Case closed.'
  'Resisting the urge to write "misc changes"|Resisted!'
  'Consulting the commit message oracle|The oracle has spoken.'
  'Reading your diff so the reviewers can skim it|Skimmable now.'
  'Making "wip" sound professional|Very professional.'
  'Flipping a coin between feat and fix|It landed.'
  'Brewing a fresh subject line|Served hot!'
  'Squeezing three hours into seventy characters|Squeezed.'
  'Looking for the why behind the what|Found the why.'
  'Polishing the imperative mood|Shiny!'
  'Negotiating with the linter in advance|Deal signed.'
  'Hiding the evidence of trial and error|No evidence left.'
  'Asking the GPUs for their honest opinion|They approve.'
  'Convincing the model that the tabs were intended|Convinced.'
  'Composing a haiku, then deleting it|It was beautiful.'
  'Removing "finally works" from the draft|And it finally works.'
  'Inventing a scope that sounds official|Very official.'
  'Giving your typo fix the gravitas it deserves|Gravitas applied.'
  'Checking whether this counts as a refactor|The verdict is in.'
  'Skipping the part where it says "stuff"|Stuff skipped.'
  'Writing history, one line at a time|History written.'
  'Explaining it to your future self|Future you says thanks!'
  'Dressing up the diff for code review|Looking sharp!'
  'Rounding "quick fix" up to "improvement"|Rounded up.'
  'Decoding what "temp2_final" was supposed to mean|Decoded, mostly.'
  'Warming up the tokens|Nice and toasty.'
  'Deciding this is definitely not a breaking change|Probably.'
  'Searching for a verb that is not "update"|Verb found!'
  'Reticulating commit splines|Splines reticulated.'
  'Fitting an epic into the subject line|It fits!'
  'Taking credit for what the compiler made you do|Credit taken.'
  'Preparing your alibi for git blame|Alibi airtight.'
  'Asking mittwald AI very nicely|It said yes!'
  'Thinking in German, answering in English|Fertig. Done.'
  'Making the changelog proud|The changelog is beaming.'
  'Distilling your diff into one honest sentence|Mostly honest.'
  'Arguing with itself about the scope|It won.'
  'Promising the reviewers it is a small change|Pinky promise.'
  'Steering clear of "various improvements"|Steered clear.'
  'Reading between the hunks|Read it all.'
  'Editing the swear words out of the summary|Squeaky clean.'
  'Trusting that the tests passed|Fingers crossed!'
  'Sorting your hunks by level of embarrassment|Sorted.'
  'Asking the reviewers to look away|They looked away.'
  'Converting caffeine into a commit message|Conversion complete.'
  'Checking whether "refactor" is technically true|Technically true.'
  'Replacing "did stuff" with actual words|Words found.'
  'Measuring the blast radius of this diff|Contained.'
  'Pretending the merge conflict never happened|What conflict?'
  'Folding forty lines of changes into one|Neatly folded.'
  'Interviewing the lines you deleted|They will be missed.'
  'Giving your variable renames a backstory|Very moving.'
  'Choosing between "add" and "introduce"|Tough call.'
  'Looking for the bug you fixed by accident|Found that one too.'
  'Writing the message your reviewers dream of|Dream delivered.'
  'Weighing the commit against the ticket|Close enough.'
  'Smoothing over the third attempt at this|First try, officially.'
  'Calculating how "minor" this change is|Minor-ish.'
  'Politely ignoring the whitespace changes|Ignored.'
  'Turning your diff into a short story|The end.'
  'Rehearsing the commit for the stand-up|Ready to present.'
  'Asking the hunks to form a single line|They lined up.'
  'Reading the diff twice, just to be sure|Sure now.'
  'Choosing the right amount of enthusiasm|Measured.'
  'Untangling what changed from what moved|Untangled.'
  'Leaving out the part about Friday afternoon|Our secret.'
  'Keeping the subject under 72 characters|With room to spare.'
  'Checking the diff for hidden feelings|None found.'
  'Compressing your intentions into plain English|Compressed.'
  'Paraphrasing the stack trace you fixed|Paraphrased.'
  'Giving the bug a proper send-off|Rest in peace, bug.'
  'Making sure "chore" is not an understatement|It is fine.'
  'Spinning up a few billion parameters|All spinning.'
  'Summarizing the meeting that led to this|Short meeting.'
  'Agreeing on a tense with the model|Imperative it is.'
  'Asking the cloud for a quick favor|Favor granted.'
  'Picking words your future self will understand|Future-proof.'
  'Separating the signal from the semicolons|Signal found.'
  'Writing a message that git log will remember|Memorable.'
  'Trimming the adjectives from your diff|Trimmed.'
  'Avoiding the word "obviously"|Obviously.'
  'Asking the model to be brief, for once|Brief enough.'
  'Describing your fix without blaming anyone|Diplomatic.'
  'Quietly forgetting the debug prints|Gone. Hopefully.'
  'Making the reviewers believe it was easy|Looks easy.'
  'Tuning the subject line to the right pitch|In tune.'
  'Checking the diff against common sense|It passed.'
  'Bribing the tokenizer with spare bytes|Bribe accepted.'
  'Finding the story hidden in your staged files|Once upon a commit.'
  'Considering the word "tweak" very carefully|Rejected.'
  'Asking the model to skip the small talk|Straight to it.'
  'Packing your changes for the trip to main|Packed and ready.'
)
FRAMES_PER_SECOND=20
MESSAGE_FRAMES=60   # frames until the next text, about 3 seconds

# On a terminal, the status is one line that is rewritten in place.
if [ -t 2 ] && [ "${TERM:-dumb}" != "dumb" ]; then
  LIVE=1
else
  LIVE=0
fi
if [ "${LIVE}" -eq 1 ] && [ -z "${NO_COLOR:-}" ]; then
  COLOR=1
  C_RED=$'\033[31m'
  C_RESET=$'\033[0m'
else
  COLOR=0
  C_RED=''
  C_RESET=''
fi

# Colors of the status text (24-bit): mittwald blue, purple, salmon and rose.
# The colors flow through the letters. The part of the text that shows the
# elapsed share of the time limit is bold and in full color, the rest is muted.
GRADIENT_STOPS=(75 56 232  155 110 216  231 160 134  182 117 133)
GRADIENT_SIZE=60    # color steps of one cycle through all stops
MUTED_GRAY=125      # the muted colors are a mix with this gray
MUTED_PERCENT=62
BRIGHT=()
MUTED=()

# Fills BRIGHT and MUTED with one escape sequence per color step.
build_gradient() {
  local stops=$(( ${#GRADIENT_STOPS[@]} / 3 ))
  local step segment from to position ease channel value bright muted
  for ((step = 0; step < GRADIENT_SIZE; step++)); do
    segment=$(( step * stops / GRADIENT_SIZE ))
    from=$(( segment * 3 ))
    to=$(( (from + 3) % ${#GRADIENT_STOPS[@]} ))
    position=$(( step * stops % GRADIENT_SIZE * 1000 / GRADIENT_SIZE ))
    ease=$(( position * position * (3000 - 2 * position) / 1000000 ))
    bright=''
    muted=''
    for channel in 0 1 2; do
      value=$(( GRADIENT_STOPS[from + channel] + (GRADIENT_STOPS[to + channel] - GRADIENT_STOPS[from + channel]) * ease / 1000 ))
      bright+=";${value}"
      muted+=";$(( value + (MUTED_GRAY - value) * MUTED_PERCENT / 100 ))"
    done
    BRIGHT[step]=$'\033'"[0;1;38;2${bright}m"
    MUTED[step]=$'\033'"[0;38;2${muted}m"
  done
}

# Draws the status line. $1 = text, $2 = frame number, $3 = number of text
# characters in full color.
draw() {
  local text="$1"
  local length=${#1}
  local line=''
  local i step
  if [ "${COLOR}" -eq 1 ]; then
    for ((i = 0; i < length; i++)); do
      step=$(( (i * GRADIENT_SIZE / length + GRADIENT_SIZE - $2 * 2 % GRADIENT_SIZE) % GRADIENT_SIZE ))
      if [ "${i}" -lt "$3" ]; then
        line+="${BRIGHT[step]}${text:i:1}"
      else
        line+="${MUTED[step]}${text:i:1}"
      fi
    done
    line+="${C_RESET}"
  else
    line="${text}"
  fi
  printf '\r%s\033[K' "${line}" >&2
}

# Replaces the status line with the status text in full color and the remark
# that says that cmai is done. $1 = index in MESSAGES, $2 = frame number.
finish_done() {
  local text="${MESSAGES[$1]%%|*}..."
  local remark="${MESSAGES[$1]#*|}"
  if [ "${LIVE}" -eq 1 ]; then
    draw "${text}" "$2" "${#text}"
    printf ' %s\n' "${remark}" >&2
  else
    printf '%s %s\n' "${text}" "${remark}" >&2
  fi
}

# Replaces the status line with a final line. $1 = color, $2 = text.
finish() {
  if [ "${LIVE}" -eq 1 ]; then
    printf '\r\033[K' >&2
  fi
  printf '%s%s%s\n' "$1" "$2" "${C_RESET}" >&2
}

# Prints the last lines of cmai output. Control characters are removed, so that
# text from the API cannot send escape sequences to the terminal.
cmai_output() {
  local file
  for file in "${ERR_FILE}" "${OUT_FILE}"; do
    [ -s "${file}" ] || continue
    LC_ALL=C tr -d '\000-\010\013-\037\177' < "${file}" |
      grep -v '^[[:space:]]*$' | tail -n 3 | cut -c 1-300 | sed 's/^/  /'
    return
  done
}

# Reports why there is no generated message. $1 = reason, $2 = "details" to add
# the cmai output.
fail() {
  finish "${C_RED}" "No commit message generated: $1"
  if [ "${2:-}" = details ]; then
    cmai_output >&2
    if [ -n "${keychain_error}" ]; then
      printf '  %s\n' "${keychain_error}" >&2
    fi
  fi
  exit 0
}

# Prints the PowerShell script that prints a generic credential from the
# Windows Credential Manager. The name of the credential is in the environment
# variable CMAI_KEYCHAIN_TARGET.
windows_credential_script() {
  cat <<'POWERSHELL_EOF'
$ErrorActionPreference = 'Stop'
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class CmaiCredential {
  [StructLayout(LayoutKind.Sequential)]
  struct Credential {
    public uint Flags; public uint Type; public IntPtr TargetName; public IntPtr Comment;
    public System.Runtime.InteropServices.ComTypes.FILETIME LastWritten;
    public uint BlobSize; public IntPtr Blob; public uint Persist; public uint AttributeCount;
    public IntPtr Attributes; public IntPtr TargetAlias; public IntPtr UserName;
  }
  [DllImport("advapi32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
  static extern bool CredReadW(string target, uint type, uint flags, out IntPtr credential);
  [DllImport("advapi32.dll")]
  static extern void CredFree(IntPtr credential);
  public static string Read(string target) {
    IntPtr pointer;
    if (!CredReadW(target, 1, 0, out pointer)) { return null; }
    try {
      Credential credential = (Credential)Marshal.PtrToStructure(pointer, typeof(Credential));
      return Marshal.PtrToStringUni(credential.Blob, (int)credential.BlobSize / 2);
    } finally { CredFree(pointer); }
  }
}
'@
$secret = [CmaiCredential]::Read($env:CMAI_KEYCHAIN_TARGET)
if ($null -eq $secret) { exit 1 }
[Console]::Out.Write($secret)
POWERSHELL_EOF
}

# Prints the API key from the system keychain. $1 = name of the keychain entry.
keychain_get() {
  local script
  case "${OSTYPE:-}" in
    darwin*)
      security find-generic-password -s "$1" -a "${KEYCHAIN_ACCOUNT}" -w
      ;;
    msys*|cygwin*)
      # -EncodedCommand takes the script as base64 of UTF-16, which needs no quoting.
      script="$(windows_credential_script | iconv -f UTF-8 -t UTF-16LE | base64 | tr -d '\r\n')"
      CMAI_KEYCHAIN_TARGET="$1" MSYS_NO_PATHCONV=1 MSYS2_ARG_CONV_EXCL='*' \
        powershell.exe -NoProfile -NonInteractive -EncodedCommand "${script}"
      ;;
    *)
      secret-tool lookup service "$1" account "${KEYCHAIN_ACCOUNT}"
      ;;
  esac
}

keychain_error=''

# git starts hooks with its own PATH, which can lack the directory of cmai.
CMAI="$(command -v cmai 2>/dev/null)" || CMAI="${HOME}/git-commit-ai/git-commit.sh"
[ -x "${CMAI}" ] || fail "cmai not found"

WORK_DIR="$(mktemp -d 2>/dev/null)" || fail "mktemp failed"
OUT_FILE="${WORK_DIR}/out"
ERR_FILE="${WORK_DIR}/err"
child=''

tick() {
  sleep 0.05 2>/dev/null || sleep 1
}

# Sends a signal to cmai and to the processes that cmai started. $1 = signal.
signal_cmai() {
  kill "-$1" -- "-${child}" 2>/dev/null || kill "-$1" "${child}" 2>/dev/null
}

# Runs from the EXIT trap.
# shellcheck disable=SC2329
cleanup() {
  [ -n "${child}" ] && signal_cmai TERM
  rm -f "${OUT_FILE}" "${ERR_FILE}"
  rmdir "${WORK_DIR}" 2>/dev/null
}
trap cleanup EXIT
# cmai runs in its own process group, so Ctrl-C does not reach cmai. The hook
# exits instead, and cleanup stops cmai.
trap '[ "${LIVE}" -eq 1 ] && printf "%s\n" "${C_RESET}" >&2; exit 130' INT
trap 'exit 143' TERM HUP

if [ "${COLOR}" -eq 1 ]; then
  build_gradient
fi

# The key goes to cmai in the environment and never touches the disk. A cmai
# version that cannot take the key from the environment uses its own key file.
api_key=''
if [ -s "${KEYCHAIN_FILE}" ]; then
  IFS= read -r keychain_entry < "${KEYCHAIN_FILE}"
  IFS= read -r -t "${KEYCHAIN_SECONDS}" api_key < <(keychain_get "${keychain_entry}" 2>/dev/null)
  api_key="${api_key%$'\r'}"
  if [ -z "${api_key}" ]; then
    keychain_error='The API key could not be read from the system keychain. Re-run the installer to store the key again.'
  fi
fi

attempts=0
exitcode=0
while [ "${attempts}" -lt "${MAX_ATTEMPTS}" ]; do
  attempts=$((attempts + 1))
  message_start=$((RANDOM % ${#MESSAGES[@]}))
  message_index="${message_start}"
  started="${SECONDS}"
  timed_out=0
  frame=0
  text=''
  # With job control, cmai gets its own process group. The hook can then stop
  # cmai together with the curl process that cmai started.
  set -m
  CMAI_API_KEY="${api_key}" "${CMAI}" --message-only > "${OUT_FILE}" 2> "${ERR_FILE}" < /dev/null &
  child=$!
  set +m
  if [ "${LIVE}" -eq 0 ]; then
    printf '%s...\n' "${MESSAGES[message_start]%%|*}" >&2
  fi

  while kill -0 "${child}" 2>/dev/null; do
    elapsed=$((SECONDS - started))
    if [ "${elapsed}" -ge "${TIMEOUT_SECONDS}" ]; then
      timed_out=1
      signal_cmai TERM
      grace=$((KILL_AFTER_SECONDS * FRAMES_PER_SECOND))
      while [ "${grace}" -gt 0 ] && kill -0 "${child}" 2>/dev/null; do
        tick
        grace=$((grace - 1))
      done
      signal_cmai KILL
      break
    fi
    if [ "${LIVE}" -eq 1 ]; then
      if [ $((frame % MESSAGE_FRAMES)) -eq 0 ]; then
        # Every MESSAGE_FRAMES frames the next text; the integer division is intended.
        # shellcheck disable=SC2017
        message_index=$(( (message_start + frame / MESSAGE_FRAMES * 7) % ${#MESSAGES[@]} ))
        text="${MESSAGES[message_index]%%|*}..."
      fi
      draw "${text}" "${frame}" "$((elapsed * ${#text} / TIMEOUT_SECONDS))"
    fi
    frame=$((frame + 1))
    tick
  done
  wait "${child}" 2>/dev/null; exitcode=$?
  child=''

  if [ "${timed_out}" -eq 0 ]; then
    break
  fi
  if [ "${attempts}" -ge "${MAX_ATTEMPTS}" ]; then
    fail "cmai timed out after ${TIMEOUT_SECONDS}s (attempt ${attempts}/${MAX_ATTEMPTS})" details
  fi
  [ "${LIVE}" -eq 1 ] || printf 'Timed out after %ss\n' "${TIMEOUT_SECONDS}" >&2
  TIMEOUT_SECONDS=$((TIMEOUT_SECONDS + (TIMEOUT_SECONDS * TIMEOUT_INCREASE_PERCENT + 99) / 100))
done

[ "${exitcode}" -eq 0 ] || fail "cmai failed (exit ${exitcode})" details
# jq for Windows ends lines with a carriage return.
COMMIT_MSG="$(tr -d '\r' < "${OUT_FILE}")"
[ -n "${COMMIT_MSG}" ] || fail "cmai returned an empty message" details

if { printf '%s\n' "${COMMIT_MSG}"; cat "${MSG_FILE}"; } > "${MSG_FILE}.tmp" &&
  mv "${MSG_FILE}.tmp" "${MSG_FILE}"; then
  finish_done "${message_index}" "${frame}"
else
  rm -f "${MSG_FILE}.tmp"
  fail "could not write ${MSG_FILE}"
fi
exit 0
